// DRAFT — Dodo Payments discovery pass 1 (2026-11-14). Review against docs/specs/IMPL-DODO.md §1.1.
import { z } from 'zod';
import { defineCredentials } from '../../contracts/credentials';

const input = z.object({
  apiKey: z.string().regex(/^dodo_(test|live)_/, 'Starts with dodo_test_ or dodo_live_'),
});

export const DODO_CREDENTIALS = defineCredentials({
  input,
  // webhookSecret is generated BY DODO (whsec_…), not by Folio. Platform: copied into env (DODO_WEBHOOK_SECRET).
  // BYOP is out of scope until ProjectCredentialStore can take a provider-generated secret — IMPL-DODO §1.11.
  runtime: input.extend({ webhookSecret: z.string().startsWith('whsec_', 'Starts with whsec_') }),
  fields: {
    apiKey: {
      label: 'API key',
      secret: true,
      placeholder: 'dodo_test_…',
      help: 'Dashboard → Developer → API Keys → Create New Key',
    },
  },
  displayHint: (c) => `${c.apiKey.slice(0, 10)}••••${c.apiKey.slice(-4)}`,
});

export type DodoCredentialsInput = z.infer<typeof input>;
export type DodoCredentials = z.infer<typeof DODO_CREDENTIALS.runtime>;
